To avoid acquiring and releasing the lock multiple times in a loop when processing batches of keys, we can introduce batch-oriented methods (`add_batch`, `remove_batch`, `filter_failed`, and `update_batch`) to `_FailedGetCache`. This allows us to acquire the lock exactly once per batch operation, significantly reducing lock contention and overhead in the critical path of existence checks and cache updates.

```python
class _FailedGetCache:
    """Bounded TTL cache for physical keys that recently failed to load."""

    def __init__(self, ttl_seconds: float, max_entries: int):
        self.ttl_seconds = ttl_seconds
        self.max_entries = max_entries
        self.cache: OrderedDict[str, float] = OrderedDict()
        self.lock = threading.Lock()

    def add(self, key: str) -> None:
        self.add_batch([key])

    def add_batch(self, keys: List[str]) -> None:
        now = time.monotonic()
        with self.lock:
            for key in keys:
                self.cache.pop(key, None)
                self.cache[key] = now
            while self.cache:
                oldest_key = next(iter(self.cache))
                oldest_time = self.cache[oldest_key]
                if (
                    len(self.cache) <= self.max_entries
                    and now - oldest_time <= self.ttl_seconds
                ):
                    break
                self.cache.popitem(last=False)

    def remove(self, key: str) -> None:
        self.remove_batch([key])

    def remove_batch(self, keys: List[str]) -> None:
        with self.lock:
            for key in keys:
                self.cache.pop(key, None)

    def contains(self, key: str) -> bool:
        now = time.monotonic()
        with self.lock:
            failed_at = self.cache.get(key)
            if failed_at is None:
                return False
            if now - failed_at > self.ttl_seconds:
                del self.cache[key]
                return False
            return True

    def filter_failed(self, keys: List[str]) -> Tuple[List[int], List[str]]:
        now = time.monotonic()
        query_indices = []
        query_keys = []
        with self.lock:
            for i, key in enumerate(keys):
                failed_at = self.cache.get(key)
                if failed_at is None:
                    query_indices.append(i)
                    query_keys.append(key)
                elif now - failed_at > self.ttl_seconds:
                    del self.cache[key]
                    query_indices.append(i)
                    query_keys.append(key)
        return query_indices, query_keys

    def update_batch(self, successes: List[str], failures: List[str]) -> None:
        now = time.monotonic()
        with self.lock:
            for key in successes:
                self.cache.pop(key, None)
            for key in failures:
                self.cache.pop(key, None)
                self.cache[key] = now
            while self.cache:
                oldest_key = next(iter(self.cache))
                oldest_time = self.cache[oldest_key]
                if (
                    len(self.cache) <= self.max_entries
                    and now - oldest_time <= self.ttl_seconds
                ):
                    break
                self.cache.popitem(last=False)

    def clear(self) -> None:
        with self.lock:
            self.cache.clear()
```

